mapper.update:
UPDATE analysis_job
   SET current_pass = #{pass}
     , total_files = 0
     , done_files = 0
     , heartbeat_at = now()
 WHERE analysis_id = #{analysisId}

UPDATE analysis_job
   SET total_files = #{totalCount}
     , done_files = #{doneCount}
     , heartbeat_at = now()
 WHERE analysis_id = #{analysisId}

UPDATE analysis_job
   SET status = #{status}
     , error_message = #{errorMessage}
     , ended_at = now()
 WHERE analysis_id = #{analysisId}
